from 写入第二遍 import add
add('10_001',7,'16:9，董白侧脸特写居画面右侧，脸朝左，鼻尖前留给青的画外位置；固定眼高机位，近处发绺沿下巴垂过。','董白完全转向青，睁大的眼睛钉在她脸上，眉毛压下来，刚才的大笑收成略张的唇。她先提醒让路，停一下，从鼻间短短呼气；说到尊重时下巴抬高，尾句向前顶出一点，发绺随头部轻摆，圆眼仍保持被质疑后的紧张。','左侧留蓝灰天空与浅灰云层，低处米灰薄尘漂成细带。','云天冷白柔光均匀，黑发内侧深冷灰，眼中小亮点清楚。','一口带恼意的短呼气，马尾轻擦衣肩，平台风声。',ja=['そこをどけって言ったでしょう。','…それに、人には敬意を払えと教えたはずよ。'],tone='先以命令压回建议，停顿后端起训诫的口吻，语尾抬高身份感。',kind='mixed',phase='state',meaning='董白侧脸圆眼、敛笑与吐气保留，自尊受触后训青。',characters=['董白'],card={'opening':'董白把协助提议听成对实力的不敬。','beats':['转脸钉视、眉压笑收','短呼气后抬下巴训诫'],'coupling':'尊重一词随着抬下巴变得居高临下。','landing':'她开始用旧战失利压青。'})
add('10_002',11,'16:9，青的后肩与长发中近景占画面左侧，镜头在背后缓慢横移，右侧留出指责来向的空隙；整镜维持看不见正脸的角度。','青听着董白的指责，扶头的手从画外落回身侧，肩膀先轻轻下沉；第一句说完，她把重心移向朝武士的一只脚，后脑与肩线随之转过小角度。长发被转动带向右侧，先分成两束，再缓缓贴回背上；听到村民受苦的问句，她停住脚，背脊逐渐挺直，抬起的肩不再紧缩。','青身侧是浅蓝灰天空，极低处保留一条灰绿平台边和米灰薄尘，远物隐在柔雾里。','正上方冷白漫射沿银发形成柔亮面，后肩下侧由地面中性弱光托起。','手臂落下的衣料声，重心移步的鞋底轻擦，风掠长发。',ja=['甲角竜と戦った時だって、村をあんなにしておいて、結局倒せなかった。','あなたの無能のせいで、どれだけの人が苦しんだか分かってる？'],tone='董白在画外连续指责，第一句列旧事，第二句以村民受苦逼问；青沉默听完。',kind='mixed',phase='process',node={'青.朝向':'从董白方向转向武士，仍未离开原站位'},meaning='董白两句画外指责，青背影与右移长发保留；沉默中形成决定。',characters=['青','董白'],card={'opening':'联手提议受拒后，青听到自己一直担忧的后果。','beats':['肩下沉、手放下','转重心带动长发横摆','听完问句停脚，背脊渐直'],'coupling':'两句画外声分别推动身体收缩和重新立直，表情留在画外。','landing':'青朝战场调整方向，准备给出自己的回答。'})
add('10_003',2,'16:9，青下半脸极特写，唇线居画面中央偏右，两侧长发框住下巴，眼睛在画外；固定机位。','青先把嘴唇轻轻合拢，吸进一小口气；她说出承认的话，唇角缓缓翘起很小的弧度，语尾吐净后下颌放松。发绺仍沿着上一镜转身的方向滑过脸侧，然后停住。','左侧窄隙是一片均匀蓝灰天空，发外下缘有淡米灰烟尘。','冷白柔光在唇与下巴形成浅亮面，发根内侧冷灰。','一次短吸气，发丝扫过衣领的轻声，风声渐弱。',ja=['…あなたの言う通り。'],tone='平静承认，语速慢半拍，语尾带已经想明白的轻松。',kind='mixed',phase='state',meaning='只见青下半脸与小幅唇线，承认后转为决断。',characters=['青'])
